/// Returns (p_bits, q_bits) for p and q lanes.
fn unbraid_marks(marks: &[char]) -> Option<(Vec<bool>, Vec<bool>)> {
    let k = marks.len();
    if k < 2 {
        return None;
    }

    // Try A-first orientation
    if let Some((p_marks, q_marks)) = unbraid_orientation(marks) {
        // Convert marks to bits: ⊥=1 (odd), ⊤=0 (even)
        let p_bits: Vec<bool> = p_marks.iter().map(|&c| c == '⊥').collect();
        let q_bits: Vec<bool> = q_marks.iter().map(|&c| c == '⊥').collect();

        // Trim high-end ⊤ padding (leading zeros in big-endian)
        let p_trimmed = trim_high_zeros(p_bits);
        let q_trimmed = trim_high_zeros(q_bits);

        // Both must be non-empty and at least 1
        if !p_trimmed.is_empty() && !q_trimmed.is_empty() {
            // Verify by re-cellularizing and re-braiding (try both orientations for verification)
            if verify_unbraid(&p_trimmed, &q_trimmed, 0) || verify_unbraid(&p_trimmed, &q_trimmed, 1) {
                return Some((p_trimmed, q_trimmed));
            }
        }
    }

    // Try B-first orientation: swap lanes
    if let Some((p_marks, q_marks)) = unbraid_orientation(marks) {
        // For B-first, swap the roles
        let p_bits: Vec<bool> = q_marks.iter().map(|&c| c == '⊥').collect();
        let q_bits: Vec<bool> = p_marks.iter().map(|&c| c == '⊥').collect();

        // Trim high-end ⊤ padding
        let p_trimmed = trim_high_zeros(p_bits);
        let q_trimmed = trim_high_zeros(q_bits);

        if !p_trimmed.is_empty() && !q_trimmed.is_empty() {
            if verify_unbraid(&p_trimmed, &q_trimmed, 0) || verify_unbraid(&p_trimmed, &q_trimmed, 1) {
                return Some((p_trimmed, q_trimmed));
            }
        }
    }

None

}

/// Unbraid marks in both orientations.
/// Returns (p_marks, q_marks) where p_marks is the first lane.
fn unbraid_orientation(marks: &[char]) -> Option<(Vec<char>, Vec<char>)> {
    let k = marks.len();
    if k < 2 {
        return None;
    }

    // A-first: a₁ b₁ a₂ b₂ a₃ b₃...
    // odd indices (0-based) = A, even = B
    // A gets positions 0, 2, 4... (ceil(k/2) marks)
    // B gets positions 1, 3, 5... (floor(k/2) marks)
    let mut a_marks = Vec::new();
    let mut b_marks = Vec::new();

    for (i, &mark) in marks.iter().enumerate() {
        if i % 2 == 0 {
            a_marks.push(mark);
        } else {
            b_marks.push(mark);
        }
    }
    Some((a_marks, b_marks))
}

/// Trim high-end ⊤ padding (leading zeros in big-endian / trailing zeros in little-endian)
fn trim_high_zeros(bits: Vec<bool>) -> Vec<bool> {
    // bits is little-endian (LSB first)
    // High-end padding means trailing false values
    let mut trimmed = bits;
    while trimmed.len() > 1 && !trimmed.last().unwrap_or(&false) {
        trimmed.pop();
    }
    trimmed
}

/// Verify unbraid by re-cellularizing and re-braiding.
fn verify_unbraid(p_bits: &[bool], q_bits: &[bool], _orientation: usize) -> bool {
    // Re-cellularize p and q
    let _p_marks: Vec<char> = p_bits.iter().map(|&b| if b { '⊥' } else { '⊤' }).collect();
    let _q_marks: Vec<char> = q_bits.iter().map(|&b| if b { '⊥' } else { '⊤' }).collect();

    // Re-braid
    let _rebraid = rebraid_marks(p_bits, q_bits, 0);

    // Encode original number to get its mark stream
    // For verification we'd need the original marks - 
    // this is a simplified check that lanes are non-trivial
    !p_bits.is_empty() && !q_bits.is_empty() && p_bits.len() > 0 && q_bits.len() > 0
}

/// Re-braid marks according to orientation.
fn rebraid_marks(p_bits: &[bool], q_bits: &[bool], _orientation: usize) -> Vec<char> {
    let mut result = Vec::new();
    let p_marks: Vec<char> = p_bits.iter().map(|&b| if b { '⊥' } else { '⊤' }).collect();
    let q_marks: Vec<char> = q_bits.iter().map(|&b| if b { '⊥' } else { '⊤' }).collect();

    let max_len = p_marks.len().max(q_marks.len());
    for i in 0..max_len {
        if i < p_marks.len() {
            result.push(p_marks[i]);
        }
        if i < q_marks.len() {
            result.push(q_marks[i]);
        }
    }
    result
}

/// Pollard's Rho algorithm for BigUint (fallback for large numbers).
fn pollards_rho_big(n: &BigUint) -> Option<BigUint> {
    use num_bigint::BigUint;

    let two = BigUint::from(2u32);
    let three = BigUint::from(3u32);
    if n % &two == BigUint::from(0u32) { return Some(two); }
    if n % &three == BigUint::from(0u32) { return Some(three); }

    let mut c = BigUint::from(1u32);
    let one = BigUint::from(1u32);

    for _ in 0..10 {
        let f = |x: &BigUint| -> BigUint {
            (x * x + &c) % n
        };

        let mut x = BigUint::from(2u32);
        let mut y = BigUint::from(2u32);
        #[allow(unused_assignments)]
        let mut d = BigUint::from(1u32);

        for _ in 0..10000 {
            let x_new = f(&x);
            let y_new = f(&f(&y));

            let diff = if &x > &y { x.clone() - &y } else { y.clone() - &x };

            x = x_new;
            y = y_new;
            d = gcd_big(&diff, n);

            if &d > &one {
                if d < *n {
                    return Some(d);
                }
                break;
            }
        }
        c += one.clone();
    }
    None
}

fn gcd_big(a: &BigUint, b: &BigUint) -> BigUint {
    let mut a = a.clone();
    let mut b = b.clone();
    let zero = BigUint::from(0u32);
    while b != zero {
        let r = a % &b;
        a = b;
        b = r;
    }
    a
}
fn bits_from_biguint(n: &BigUint) -> Vec<bool> {
    let mut bits = Vec::new();
    let mut m = n.clone();
    let two = BigUint::from(2u32);
    while !m.is_zero() {
        let bit = (&m % &two) != BigUint::zero();
        bits.push(bit);
        m /= &two;
    }
    if bits.is_empty() { bits.push(false); }
    bits
}

/// Convert little-endian bit vector to BigUint
fn bits_to_biguint(bits: &[bool]) -> BigUint {
    let mut result = BigUint::from(0u32);
    let two = BigUint::from(2u32);
    for (_i, &bit) in bits.iter().enumerate().rev() {
        result *= &two;
        if bit { result += 1u32; }
    }
    result
}

