/// Factor a decimal N: trial division to a fixed bound, then Pollard's rho for
/// anything past it. Each factor is separately encoded and read back through
/// tri_ancestral_word_verdict for reference — that verdict is a closure
/// property of encode()'s own construction (every parity branch opens and
/// fuses before the next), so it holds for every n and confirms nothing about
/// whether p, q are the real factors. The arithmetic check p×q=N does that.
pub fn factor_decimal(n_str: &str) -> String {
    let n: BigUint = match n_str.trim().parse() {
        Ok(v) => v,
        Err(_) => return format!("native_numeral factor: '{}' is not a valid non-negative integer", n_str),
    };

    if n.is_zero() {
        return "N = 0\nD(0) = ⊢⊙⊡⊣\np = 0, q = 0\np × q = 0\n".to_string();
    }
    if n == BigUint::from(1u32) {
        return format!("N = 1\nD(1) = {}\n1 is a unit; it has no prime factorization\n", encode("1"));
    }

    let word = encode(n_str);

    match find_factor(&n) {
        Some((p, q)) => {
            let mut report = String::new();
            report.push_str(&format!("N = {}\n", n_str));
            report.push_str(&format!("D(N) = {}\n", word));
            report.push_str("\nfactor (trial division to 10^6, then Pollard's rho):\n");
            report.push_str(&format!("p = {}\n", p));
            report.push_str(&format!("D(p) = {}\n", encode(&p.to_string())));
            report.push_str(&format!("q = {}\n", q));
            report.push_str(&format!("D(q) = {}\n", encode(&q.to_string())));
            report.push_str("\nVerification:\n");
            report.push_str(&format!("  p × q = N: {}\n", &p * &q == n));
            report.push_str(&format!("  D(N) tri-ancestral verdict: {}\n", tri_ancestral_word_verdict(&word).map(|c| c.to_string()).unwrap_or("?".to_string())));
            report.push_str(&format!("  D(p) tri-ancestral verdict: {}\n", tri_ancestral_word_verdict(&encode(&p.to_string())).map(|c| c.to_string()).unwrap_or("?".to_string())));
            report.push_str(&format!("  D(q) tri-ancestral verdict: {}\n", tri_ancestral_word_verdict(&encode(&q.to_string())).map(|c| c.to_string()).unwrap_or("?".to_string())));
            report
        }
        None => format!(
            "N = {}\nD(N) = {}\n\nno factor found by trial division (bound 10^6) or Pollard's rho.\nN is prime, or its smallest factor lies beyond both methods' reach.\n",
            n_str, word
        ),
    }
}

/// Trial division to a fixed bound, then Pollard's rho. None means neither
/// method split N — most likely N is prime.
fn find_factor(n: &BigUint) -> Option<(BigUint, BigUint)> {
    let limit = 1_000_000u64;
    for p_val in 2..=limit {
        let p_big = BigUint::from(p_val);
        if &p_big * &p_big > *n {
            break;
        }
        if n % &p_big == BigUint::from(0u32) {
            let q_big = n / &p_big;
            return Some((p_big, q_big));
        }
    }
    pollards_rho_big(n).map(|p| {
        let q = n / &p;
        if p <= q { (p, q) } else { (q, p) }
    })
}

/// Pollard's Rho algorithm for BigUint (fallback for large numbers).
fn pollards_rho_big(n: &BigUint) -> Option<BigUint> {
    use num_bigint::BigUint;

    let two = BigUint::from(2u32);
    let three = BigUint::from(3u32);
    if n % &two == BigUint::from(0u32) { return Some(two); }
    if n % &three == BigUint::from(0u32) { return Some(three); }

    let mut c = BigUint::from(1u32);
    let one = BigUint::from(1u32);

    for _ in 0..10 {
        let f = |x: &BigUint| -> BigUint {
            (x * x + &c) % n
        };

        let mut x = BigUint::from(2u32);
        let mut y = BigUint::from(2u32);
        #[allow(unused_assignments)]
        let mut d = BigUint::from(1u32);

        for _ in 0..10000 {
            let x_new = f(&x);
            let y_new = f(&f(&y));

            let diff = if &x > &y { x.clone() - &y } else { y.clone() - &x };

            x = x_new;
            y = y_new;
            d = gcd_big(&diff, n);

            if &d > &one {
                if d < *n {
                    return Some(d);
                }
                break;
            }
        }
        c += one.clone();
    }
    None
}

fn gcd_big(a: &BigUint, b: &BigUint) -> BigUint {
    let mut a = a.clone();
    let mut b = b.clone();
    let zero = BigUint::from(0u32);
    while b != zero {
        let r = a % &b;
        a = b;
        b = r;
    }
    a
}

