332	/// Modular exponentiation, base^exp mod modulus, walking exp's own bits
333	/// LSB-first via to_bits_low_first — the same bit vector encode() builds its
334	/// word from. Square every step; multiply the base in only where the bit is
335	/// set, exactly the ⊥/odd branch encode() already marks per cell.
336	fn mod_pow_walk(base: &BigUint, exp_bits: &[bool], modulus: &BigUint) -> BigUint {
337	    let mut result = BigUint::from(1u32);
338	    let mut b = base % modulus;
339	    for &bit in exp_bits {
340	        if bit {
341	            result = (&result * &b) % modulus;
342	        }
343	        b = (&b * &b) % modulus;
344	    }
345	    result
