fn pow2(k: usize) -> BigUint {
    let mut r = BigUint::from(1u32);
    let two = BigUint::from(2u32);
    for _ in 0..k { r *= &two; }
    r
}

/// The real unbraid: not deinterleaving N's own bits (that fails against real
/// multiplication, checked and reported), but propagating N's constraint back
/// onto p and q's UNKNOWN bits directly. p and q are fixed from the MSB down;
/// each unknown suffix ranges over every value it could still take, giving an
/// EXACT range for p*q (monotonic in both factors, so [p_lo*q_lo, p_hi*q_hi]
/// is exact, not an approximation). N outside that range means backtrack —
/// a real refutation, not a guess. Each bit genuinely lives at N (untouched),
/// then T or F once fixed, and every choice is B (both still live) until the
/// range check kills one side.
///
/// Top bit of each factor is forced 1 (that's what "m-bit number" means) and
/// bottom bit forced 1 (both factors are odd; the small-prime peel upstream
/// already took 2). Returns (p, q, nodes visited) on success.
struct UnbraidBudget {
    nodes: u64,
    cap: u64,
}

fn unbraid_search(
    n: &BigUint,
    p_bits: usize,
    q_bits: usize,
    p_prefix: &mut Vec<bool>,
    q_prefix: &mut Vec<bool>,
    budget: &mut UnbraidBudget,
) -> Option<(BigUint, BigUint)> {
    budget.nodes += 1;
    if budget.nodes > budget.cap {
        return None;
    }

    let bound = |prefix: &[bool], total_bits: usize| -> (BigUint, BigUint) {
        let mut fixed = BigUint::zero();
        for (i, &b) in prefix.iter().enumerate() {
            if b {
                fixed += pow2(total_bits - 1 - i);
            }
        }
        let free = total_bits - prefix.len();
        let hi = &fixed + &(pow2(free) - BigUint::from(1u32));
        (fixed, hi)
    };

    let (p_lo, p_hi) = bound(p_prefix, p_bits);
    let (q_lo, q_hi) = bound(q_prefix, q_bits);
    let range_lo = &p_lo * &q_lo;
    let range_hi = &p_hi * &q_hi;
    if *n < range_lo || *n > range_hi {
        return None; // refuted: N cannot live in this branch, backtrack
    }

    if p_prefix.len() == p_bits && q_prefix.len() == q_bits {
        // fully fixed both sides — p_lo==p_hi==p, q_lo==q_hi==q here
        if &p_lo * &q_lo == *n {
            return Some((p_lo, q_lo));
        }
        return None;
    }

    // extend whichever side has fewer bits fixed, keeping both prefixes growing evenly
    let extend_p = p_prefix.len() <= q_prefix.len() && p_prefix.len() < p_bits;
    let (target, total, prefix) = if extend_p {
        (p_bits, p_bits, &mut *p_prefix)
    } else {
        (q_bits, q_bits, &mut *q_prefix)
    };
    let _ = target;
    let last_bit = prefix.len() == total - 1; // the LSB — factors are odd, forced 1

    let bits_to_try: &[bool] = if last_bit { &[true] } else { &[true, false] };
    for &bit in bits_to_try {
        prefix.push(bit);
        let result = if extend_p {
            unbraid_search(n, p_bits, q_bits, p_prefix, q_prefix, budget)
        } else {
            unbraid_search(n, p_bits, q_bits, p_prefix, q_prefix, budget)
        };
        prefix_pop(if extend_p { p_prefix } else { q_prefix });
        if result.is_some() {
            return result;
        }
        if budget.nodes > budget.cap {
            return None;
        }
    }
    None
}

fn prefix_pop(v: &mut Vec<bool>) {
    v.pop();
}

/// Try every (p_bits, q_bits) split consistent with N's own bit length, real
/// unbraiding each. Returns the factor pair, or None with the node count spent
/// if the budget ran out first — that count is the honest number to report,
/// not a guess at how close it got.
pub fn unbraid_report(n_str: &str, node_cap: u64) -> String {
    let n: BigUint = match n_str.trim().parse() {
        Ok(v) => v,
        Err(_) => return format!("native_numeral unbraid: '{}' is not a valid non-negative integer", n_str),
    };
    if n.is_zero() || n == BigUint::from(1u32) {
        return format!("N = {} has no two-factor unbraid\n", n_str);
    }
    let total_bits = n.bits() as usize;
    let mut total_nodes = 0u64;
    for p_bits in 2..=(total_bits / 2 + 1) {
        let q_bits_candidates = [total_bits + 1 - p_bits, total_bits - p_bits];
        for &q_bits in q_bits_candidates.iter() {
            if q_bits < p_bits || q_bits == 0 {
                continue;
            }
            let mut p_prefix = vec![true];
            let mut q_prefix = vec![true];
            let mut budget = UnbraidBudget { nodes: 0, cap: node_cap.saturating_sub(total_nodes) };
            if budget.cap == 0 {
                return format!(
                    "N = {}\nunbraid exhausted the node budget ({}) before finishing every split.\n",
                    n_str, node_cap
                );
            }
            let found = unbraid_search(&n, p_bits, q_bits, &mut p_prefix, &mut q_prefix, &mut budget);
            total_nodes += budget.nodes;
            if let Some((p, q)) = found {
                return format!(
                    "N = {}\nunbraid found p={} bits, q={} bits after {} node(s):\np = {}\nq = {}\np × q = N: {}\n",
                    n_str, p_bits, q_bits, total_nodes, p, q, &p * &q == n
                );
            }
        }
    }
    format!(
        "N = {}\nunbraid exhausted every (p_bits, q_bits) split within {} node(s) total, no factor found.\n",
        n_str, total_nodes
    )
}

