86	/// n as bits, least significant first. `true` is an odd (1) bit.
87	fn to_bits_low_first(n: &BigUint) -> alloc::vec::Vec<bool> {
88	    let mut bits = alloc::vec::Vec::new();
89	    let mut m = n.clone();
90	    let two = BigUint::from(2u32);
91	    while !m.is_zero() {
92	        let bit = (&m % &two) != BigUint::zero();
93	        bits.push(bit);
94	        m /= &two;
95	    }
96	    bits
97	}
