105	    o.push_str("  interlace <p> <q>  build D(p,q) via the Λ codec and decode it straight back\n");
106	    o.push_str("  deinterlace <W>    Λ(W_N) deinterlace: extract (p,q) from a D(p,q) word\n");
107	    o.push_str("  primetest <n>      Miller-Rabin against the 12-witness set, with the held-witness count\n");
108	    o.push_str("  gcd <a> <b>        the Belnap binary-GCD walk between two decimal integers, with its trace\n");
109	    o.push_str("  unbraid <n> [cap]  factor N by propagating its own bits onto p and q from the MSB down\n");
110	    o.push_str("  help          this list");
